output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited inside single-file shelf aisles where shelves flank both sides of the customer.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A customer must not push a cart from a wider aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              },
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "cartless_only_near_parked_cart",
    "text": "Except at the entrance cart bay, customers without a cart may move only in a single-file shelf aisle or at its immediately adjacent cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessMovementZone": {
          "or": [
            "singleFileShelfAisle",
            "aisleMouth",
            "entranceCartBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessMovementZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_parking",
    "text": "Whenever a customer parks or releases a cart, they are obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_at_wide_aisle_mouth",
    "text": "Carts may be parked only in wide unobstructed main-aisle mouths, not in shelf aisles or constricted browsing cells.",
    "abstraction": {
      "state_properties": {
        "wideUnobstructedCell": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "singleFileAisleMouth": {
          "and": [
            "wideUnobstructedCell",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "singleFileAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_aisle_interactions",
    "text": "Interactions in open shopping aisles must be done with a cart unless the interaction is retrieving a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "openShoppingAisle": {
          "not": "singleFileShelfAisle"
        }
      },
      "events": {
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShoppingAisle",
          {
            "not": "hasCart"
          },
          {
            "not": "retrieveCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_side_shelf_bays",
    "text": "At ordinary side-shelf browsing bays, customers are expected to keep their cart while interacting with the shelf.",
    "abstraction": {
      "state_properties": {
        "flankedShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "sideShelfBay": {
          "and": [
            "adjShelf",
            {
              "not": "flankedShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "sideShelfBay",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_single_file_pick",
    "text": "After selecting an item while cartless in a single-file shelf aisle, the customer must return to and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartlessSingleFileInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileInteraction",
      "discharge": "hasCart"
    }
  }
]
